    struct key *default_keyring = NULL;
    int ret = 0;

    if (*_dest_keyring) {
        dest_keyring = *(_dest_keyring);
    } else {
        default_keyring = keyring_lookup(KEY_TYPE_USER);
        if (!default_keyring) {
            ret = -ENOENT;
            goto out;
        }

        if (security_permission(current_cred(), default_keyring, KEY_NEED_SEARCH)) {
            ret = -EACCES;
            goto out;
        }

        dest_keyring = default_keyring;
    }

    *_dest_keyring = dest_keyring;
out:
    return ret;
}

#include <linux/key.h>
#include <linux/errno.h>

int construct_dest_keyring(struct key **_dest_keyring) {
    struct key *dest_keyring;

    if (*_dest_keyring) {
        /* A keyring is already provided, use it */
        dest_keyring = *(_dest_keyring);
        if (key_validate(dest_keyring) < 0) {
            return -EINVAL;
        }
    } else {
        /* No keyring provided, find a default one */
        dest_keyring = find_default_keyring();
        if (IS_ERR(dest_keyring)) {
            return PTR_ERR(dest_keyring);
        }

        /* Check permissions */
        if (key_permission(current_cred(), dest_keyring, KEY_NEED_SEARCH) < 0) {
            key_put(dest_keyring);
            return -EACCES;
        }
    }

    *_dest_keyring = dest_keyring;
    return 0;
}
